// AI answer-engine referrer detection for analytics.
// The dataLayer "ai_referral" event lets GTM/GA4 segment AI-referred traffic
// (see the AI referral tracking recipe in the seo-strategy guide).
export const AI_REFERRERS = [
  "chat.openai.com",
  "chatgpt.com",
  "perplexity.ai",
  "claude.ai",
  "gemini.google.com",
  "copilot.microsoft.com",
  "you.com",
];

export function getAiReferrer(referrer: string): string | null {
  if (!referrer) return null;
  return AI_REFERRERS.find((host) => referrer.includes(host)) ?? null;
}
