"use client";

import { ReactLenis, useLenis } from "lenis/react";
import { useCallback, useEffect, useRef } from "react";

function LenisOnDemandRaf() {
  const lenis = useLenis();
  const rafId = useRef<number | null>(null);

  const stopRaf = useCallback(() => {
    if (rafId.current !== null) {
      cancelAnimationFrame(rafId.current);
      rafId.current = null;
    }
  }, []);

  const runRaf = useCallback(
    (time: number) => {
      if (!lenis) {
        rafId.current = null;
        return;
      }

      lenis.raf(time);

      if (lenis.isScrolling) {
        rafId.current = requestAnimationFrame(runRaf);
      } else {
        rafId.current = null;
      }
    },
    [lenis],
  );

  const startRaf = useCallback(() => {
    if (!lenis || rafId.current !== null) return;
    rafId.current = requestAnimationFrame(runRaf);
  }, [lenis, runRaf]);

  useEffect(() => {
    if (!lenis) return;

    const controller = new AbortController();
    const inputEvents: Array<keyof WindowEventMap> = [
      "wheel",
      "touchstart",
      "touchmove",
      "touchend",
      "keydown",
      "click",
    ];

    inputEvents.forEach((eventName) => {
      window.addEventListener(eventName, startRaf, {
        capture: true,
        passive: true,
        signal: controller.signal,
      });
    });

    return () => {
      controller.abort();
      stopRaf();
    };
  }, [lenis, startRaf, stopRaf]);

  return null;
}

export function SmoothScroll({ children }: { children: React.ReactNode }) {
  // Snappier lerp and shorter duration for responsive scroll feel
  return (
    <ReactLenis
      root
      options={{ lerp: 0.1, duration: 1.2, smoothWheel: true, autoRaf: false }}
    >
      <LenisOnDemandRaf />
      {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
      {children as any}
    </ReactLenis>
  );
}
