"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import Image from "next/image"
import { Container } from "@/components/ui/container"
import { Button } from "@/components/ui/button"
import { ThemeToggle } from "@/components/theme-toggle"
import { navLinks, industryLinks } from "@/lib/constants"
import { Sheet, SheetContent, SheetTrigger, SheetTitle } from "@/components/ui/sheet"
import { ChevronDown, Menu } from "lucide-react"
import { useState } from "react"
import { useBookingUrl } from "@/lib/use-booking-url"

type NavLinkItem = { href: string; label: string }

function NavLink({
  link,
  pathname,
  className,
  onAnchorClick,
  onNavigate,
}: {
  link: NavLinkItem
  pathname: string
  className: string
  onAnchorClick?: (e: React.MouseEvent<HTMLAnchorElement>, href: string) => void
  onNavigate?: () => void
}) {
  if (link.href.startsWith("#")) {
    if (pathname === "/") {
      return (
        <a
          href={link.href}
          onClick={(e) => onAnchorClick?.(e, link.href)}
          className={className}
          data-gtm-nav={link.label}
        >
          {link.label}
        </a>
      )
    }
    return (
      <Link
        href={`/${link.href}`}
        className={className}
        onClick={onNavigate}
        data-gtm-nav={link.label}
      >
        {link.label}
      </Link>
    )
  }
  return (
    <Link href={link.href} className={className} onClick={onNavigate} data-gtm-nav={link.label}>
      {link.label}
    </Link>
  )
}

