export function Navbar() {
  const pathname = usePathname()
  const [isOpen, setIsOpen] = useState(false)
  const bookingUrl = useBookingUrl()

  const scrollToSection = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault()
    const element = document.querySelector(href)
    if (element) {
      element.scrollIntoView({ behavior: "smooth" })
      setIsOpen(false)
    }
  }

  return (
    <header className="sticky top-0 inset-x-0 w-full bg-background/95 lg:bg-background/80 backdrop-blur-lg border-b border-border z-50">
      <Container className="relative flex items-center justify-between h-16">
        <Link href="/" className="flex items-center gap-2">
          <div className="h-8 w-auto flex items-center justify-center">
            <Image
              src="/logo.png"
              alt="Arbor AI Studio Logo"
              width={301}
              height={277}
              className="h-full w-auto object-contain dark:brightness-0 dark:invert"
            />
          </div>
          <span className="text-xl font-semibold">Arbor AI Studio</span>
        </Link>

        {/* Desktop Navigation */}
        <nav className="hidden lg:block">
          <ul className="flex items-center justify-center gap-8">
            {navLinks.slice(0, 2).map((link) => (
              <li key={link.href}>
                <NavLink
                  link={link}
                  pathname={pathname}
                  className="text-sm hover:text-primary transition-colors cursor-pointer"
                  onAnchorClick={scrollToSection}
                />
              </li>
            ))}
            <IndustriesDropdown />
            {navLinks.slice(2).map((link) => (
              <li key={link.href}>
                <NavLink
                  link={link}
                  pathname={pathname}
                  className="text-sm hover:text-primary transition-colors cursor-pointer"
                  onAnchorClick={scrollToSection}
                />
              </li>
            ))}
          </ul>
        </nav>

        <div className="flex items-center gap-4">
          <ThemeToggle />
          <Button asChild className="hidden lg:flex" id="btn-nav-book-audit">
            <a href={bookingUrl} target="_blank" rel="noopener noreferrer">
              Book a Workflow Fit Call
            </a>
          </Button>

          <Sheet open={isOpen} onOpenChange={setIsOpen}>
            <SheetTrigger asChild>
              <Button variant="ghost" size="icon" className="lg:hidden" aria-controls="mobile-menu">
                <Menu className="h-6 w-6" />
                <span className="sr-only">Toggle menu</span>
              </Button>
            </SheetTrigger>
            <SheetContent side="right" id="mobile-menu">
              <SheetTitle className="sr-only">Navigation Menu</SheetTitle>
              <div className="flex flex-col gap-6 mt-8">
                <Link href="/" className="flex items-center gap-2" onClick={() => setIsOpen(false)}>
                  <div className="h-8 w-auto flex items-center justify-center">
                    <Image
                      src="/logo.png"
                      alt="Arbor AI Studio Logo"
                      width={301}
                      height={277}
                      className="h-full w-auto object-contain dark:brightness-0 dark:invert"
                    />
                  </div>
                  <span className="text-xl font-semibold">Arbor AI Studio</span>
                </Link>
                <nav className="flex flex-col gap-4">
                  {navLinks.map((link) => (
                    <div key={link.href}>
                      <NavLink
                        link={link}
                        pathname={pathname}
                        className="text-lg font-medium text-foreground hover:text-primary transition-colors"
                        onAnchorClick={scrollToSection}
                        onNavigate={() => setIsOpen(false)}
                      />
                    </div>
                  ))}
                  <div>
                    <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">
                      Industries
                    </p>
                    <div className="flex flex-col gap-3 border-l border-border pl-4">
                      {industryLinks.map((industry) => (
                        <Link
                          key={industry.href}
                          href={industry.href}
                          className="text-lg font-medium text-foreground hover:text-primary transition-colors"
                          onClick={() => setIsOpen(false)}
                          data-gtm-nav={`Industries: ${industry.label}`}
                        >
                          {industry.label}
                        </Link>
                      ))}
                    </div>
                  </div>
                  <Button asChild className="mt-4 w-full" id="btn-nav-book-audit-mobile">
                    <a href={bookingUrl} target="_blank" rel="noopener noreferrer" onClick={() => setIsOpen(false)}>
                      Book a Workflow Fit Call
                    </a>
                  </Button>
                </nav>
              </div>
            </SheetContent>
          </Sheet>
        </div>
      </Container>
    </header>
  )
}
