"use client";

import { useState, useEffect, useRef } from "react";
import Script from "next/script";
import { usePathname } from "next/navigation";
import { TRACKING_IDS } from "@/lib/constants";
import { useCookieConsent } from "@/hooks/use-cookie-consent";
import { getAiReferrer } from "@/lib/ai-referrer";
import { CookieConsentBannerTemporary } from "@/components/cookie-consent-banner-temporary";

declare global {
  interface Window {
    gtag: (...args: unknown[]) => void;
    dataLayer: unknown[];
    fbq: (...args: unknown[]) => void;
  }
}

export function Analytics() {
  const pathname = usePathname();
  const {
    consentGiven,
    preferences,
    mounted,
    acceptAll,
    rejectAll,
  } = useCookieConsent();

  const [pixelReady, setPixelReady] = useState(false);

  // Unified Consent & SPA PageView Tracker
  // This string-ref guarantees exactly ONE PageView is fired per navigation, but fully supports A -> B -> A back-navigation.
  const lastTrackedPath = useRef<string | null>(null);

  useEffect(() => {
    if (!mounted || !consentGiven) return;

    if (typeof window !== 'undefined') {
      if (window.gtag) {
        window.gtag('consent', 'update', {
          'analytics_storage': 'granted',
          'ad_storage': preferences.marketing ? 'granted' : 'denied',
          'ad_user_data': preferences.marketing ? 'granted' : 'denied',
          'ad_personalization': preferences.marketing ? 'granted' : 'denied',
        });
      }

      if (window.fbq) {
        window.fbq('consent', preferences.marketing ? 'grant' : 'revoke');

        // Target: Only track PageView if they consented AND we haven't tracked this EXACT path in the current sequence!
        if (preferences.marketing && lastTrackedPath.current !== pathname) {
          window.fbq('track', 'PageView');
          lastTrackedPath.current = pathname;
        }
      }
    }
  }, [consentGiven, preferences, pathname, mounted, pixelReady]);

  // AI answer-engine referral detection: push one dataLayer event per session
  // when the visitor arrived from an AI chatbot (ChatGPT, Claude, Perplexity, etc).
  useEffect(() => {
    if (!mounted || !consentGiven || typeof window === 'undefined') return;

    try {
      if (sessionStorage.getItem('ai_referral_tracked')) return;
      const aiReferrer = getAiReferrer(document.referrer);
      if (aiReferrer && window.dataLayer) {
        window.dataLayer.push({
          event: 'ai_referral',
          traffic_source_type: 'ai_search',
          ai_referrer: aiReferrer,
        });
        sessionStorage.setItem('ai_referral_tracked', '1');
      }
    } catch {
      // sessionStorage unavailable (private mode); skip silently
    }
  }, [consentGiven, mounted]);

  if (!mounted) return null;

  const isLocalhost =
    typeof window !== "undefined" &&
    (window.location.hostname === "localhost" ||
      window.location.hostname === "127.0.0.1");

  // Local development preview: force the consent banner to render (ignoring
  // stored consent and without loading any tracking scripts) via
  // http://localhost:3000/?consent-preview
  if (
    isLocalhost &&
    new URLSearchParams(window.location.search).has("consent-preview")
  ) {
    return (
      <CookieConsentBannerTemporary
        acceptAll={acceptAll}
        rejectAll={rejectAll}
      />
    );
  }

  // Prevent tracking in local development or E2E tests
  // We check hostname for local dev and standard automation flags (webdriver) or UserAgent for CI/Playwright tests
  const isDev =
    typeof window !== "undefined" &&
    (isLocalhost ||
      window.navigator.userAgent.includes("Playwright") ||
      window.navigator.webdriver === true);

  if (isDev) {
    console.log("Analytics disabled: Local/Test environment detected.");
    return null;
  }

  return (
    <>
      {/* --- Scripts based on Granular Consent --- */}

      {/* Consent Mode Initialization (Must be first) */}
      <Script
        id="consent-mode"
        strategy="beforeInteractive"
        dangerouslySetInnerHTML={{
          __html: `
            window.dataLayer = window.dataLayer || [];
            function gtag(){dataLayer.push(arguments);}
            gtag('consent', 'default', {
              'ad_storage': 'denied',
              'analytics_storage': 'denied',
              'ad_user_data': 'denied',
              'ad_personalization': 'denied',
              'wait_for_update': 500
            });
            gtag('js', new Date());
          `,
        }}
      />

      {/* Everything below loads only after consent (OK / close on the banner,
          or a stored choice). No tracking scripts run before that. */}
      {consentGiven && (
        <>
          {/* GTM */}
          <Script
            id="google-tag-manager"
            strategy="afterInteractive"
            dangerouslySetInnerHTML={{
              __html: `(function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':new Date().getTime(),event:'gtm.js'});var f=d.getElementsByTagName(s)[0],j=d.createElement(s),dl=l!='dataLayer'?'&l='+l:'';j.async=true;j.src='https://www.googletagmanager.com/gtm.js?id='+i+dl;f.parentNode.insertBefore(j,f);})(window,document,'script','dataLayer','${TRACKING_IDS.GTM}');`,
            }}
          />

          {/* Analytics Category: Apollo (gated by analytics preference) */}
          {preferences.analytics && (
            <Script
              id="apollo-tracker"
              strategy="afterInteractive"
              dangerouslySetInnerHTML={{
                __html: `function initApollo(){var n=Math.random().toString(36).substring(7),o=document.createElement("script");
o.src="https://assets.apollo.io/micro/website-tracker/tracker.iife.js?nocache="+n,o.async=!0,o.defer=!0,
o.onload=function(){window.trackingFunctions.onLoad({appId:"${TRACKING_IDS.APOLLO}"})},
document.head.appendChild(o)}initApollo();`,
              }}
            />
          )}

          {/* Clarity */}
          <Script
            id="microsoft-clarity"
            strategy="afterInteractive"
            dangerouslySetInnerHTML={{
              __html: `
                  (function(c,l,a,r,i,t,y){
                      c[a]=c[a]||function(){(c[a].q=c[a].q||[]).push(arguments)};
                      t=l.createElement(r);t.async=1;t.src="https://www.clarity.ms/tag/"+i;
                      y=l.getElementsByTagName(r)[0];y.parentNode.insertBefore(t,y);
                  })(window, document, "clarity", "script", "${TRACKING_IDS.CLARITY}");
                `,
            }}
          />

          {/* Marketing Category: Meta Pixel Init & Consent Guard */}
          {/* React now handles the 'PageView' physically to bypass broken GTM Consent Mode overrides */}
          <Script
            id="meta-pixel-init"
            strategy="afterInteractive"
            onLoad={() => setPixelReady(true)}
            dangerouslySetInnerHTML={{
              __html: `
                !function(f,b,e,v,n,t,s)
                {if(f.fbq)return;n=f.fbq=function(){n.callMethod?
                n.callMethod.apply(n,arguments):n.queue.push(arguments)};
                if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version='2.0';
                n.queue=[];t=b.createElement(e);t.async=!0;
                t.src=v;s=b.getElementsByTagName(e)[0];
                s.parentNode.insertBefore(t,s)}(window, document,'script',
                'https://connect.facebook.net/en_US/fbevents.js');

                // GDPR Zero-Tracking Default: Revoke consent strictly before init
                fbq('consent', 'revoke');
                fbq('init', '${TRACKING_IDS.META_PIXEL}');

                // Note: We deliberately skip fbq('track', 'PageView') here.
                // It will be dynamically triggered by the React useEffect exactly when consent is granted.
              `,
            }}
          />
        </>
      )}


      {/* --- Consent Banner (temporary notice while the full banner is redesigned) --- */}
      {!consentGiven && (
        <CookieConsentBannerTemporary
          acceptAll={acceptAll}
          rejectAll={rejectAll}
        />
      )}
    </>
  );
}
